def process_orders(orders):
    total_revenue = 0.0
    unprocessed = []
    for item in orders:
        try:
            total_revenue += item['amount'] * item['quantity']
        except (KeyError, TypeError):
            try:
                unprocessed.append(item['id'])
            except (KeyError, TypeError):
                unprocessed.append(None)
    return total_revenue, unprocessed
